-- Optimistic concurrency for financial read/validate/write batches.
CREATE TABLE IF NOT EXISTS financial_revisions (user_id TEXT PRIMARY KEY,revision INTEGER NOT NULL DEFAULT 0 CONSTRAINT financial_revision_conflict CHECK(revision>=0));
CREATE TRIGGER IF NOT EXISTS financial_transactions_insert AFTER INSERT ON transactions BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(NEW.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_transactions_update AFTER UPDATE ON transactions BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(NEW.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_transactions_delete AFTER DELETE ON transactions BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(OLD.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_positions_insert AFTER INSERT ON positions BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(NEW.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_positions_update AFTER UPDATE OF quantity,avg_price,cost_basis,fees_total,currency,broker,portfolio_id,stock_key,exchange,prefer_tr,active,frozen_qty,frozen_until ON positions BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(NEW.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_positions_delete AFTER DELETE ON positions BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(OLD.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
