CREATE TRIGGER IF NOT EXISTS financial_portfolio_market_settings_delete AFTER DELETE ON portfolio_market_settings BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(OLD.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_portfolios_insert AFTER INSERT ON portfolios BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(NEW.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_portfolios_update AFTER UPDATE ON portfolios BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(NEW.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_portfolios_delete AFTER DELETE ON portfolios BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(OLD.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER IF NOT EXISTS financial_fund_transactions_insert AFTER INSERT ON fund_transactions BEGIN INSERT INTO financial_revisions(user_id,revision) VALUES(NEW.user_id,1) ON CONFLICT(user_id) DO UPDATE SET revision=revision+1; END;
